from dynamodb.entity.todo_list.todo_list_entity import TodoListEntity
from dynamodb.entity.todo_list.todo_list_entity_repo import TodoListEntityRepo, TodoListQueryResponse
from dynamodb.entity.todo_list.todo_list_entity_service import TodoListEntityService


class TodoListService:

    entity_service = TodoListEntityService(TodoListEntityRepo())

    @staticmethod
    def put_todo_list(todo_list: TodoListEntity) -> TodoListEntity:
        return TodoListService.entity_service.put_todo_list(todo_list=todo_list)

    @staticmethod
    def find_all_todo_lists() -> TodoListQueryResponse:
        return TodoListService.entity_service.find_all_todo_lists()
